<?php
declare(strict_types=1);
require_once dirname(__DIR__).'/includes/functions.php';
require_admin();$pdo=db();$labels=point_setting_labels();$settings=get_point_settings($pdo);$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$incoming=$_POST['settings']??[];$new=[];foreach($labels as $key=>$meta){$value=filter_var($incoming[$key]??null,FILTER_VALIDATE_INT);if($value===false||$value<0||$value>1000){$error='Every point value must be a whole number from 0 to 1000.';break;}$new[$key]=(int)$value;}if(!$error){try{$pdo->beginTransaction();$upsert=$pdo->prepare('INSERT INTO point_settings (setting_key,setting_value) VALUES (?,?) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value)');foreach($new as $key=>$value)$upsert->execute([$key,$value]);recalculate_all_points($pdo);$pdo->commit();flash('success','Point settings saved. All session points and rankings were recalculated.');redirect('admin/settings.php');}catch(Throwable $exception){if($pdo->inTransaction())$pdo->rollBack();error_log('Settings update failed: '.$exception->getMessage());$error='The settings could not be saved.';}}$settings=array_replace($settings,$new);}
$groups=[];foreach($labels as $key=>[$group,$label])$groups[$group][$key]=$label;$pageTitle='Point settings';$adminPage='settings';require dirname(__DIR__).'/includes/admin-header.php';
?>
<div class="admin-titlebar"><div><p class="eyebrow">Scoring engine</p><h1>Point settings</h1><p>Changing a value recalculates every historical session and monthly ranking.</p></div></div><?php if($error):?><div class="notice notice-error" role="alert"><?=e($error)?></div><?php endif;?>
<form method="post"><?=csrf_field()?><div class="settings-grid"><?php foreach($groups as $group=>$items):?><section class="surface settings-group"><h2><?=e($group)?></h2><?php foreach($items as $key=>$label):?><div class="field"><label for="setting-<?=e($key)?>"><?=e($label)?></label><input id="setting-<?=e($key)?>" name="settings[<?=e($key)?>]" type="number" min="0" max="1000" step="1" required value="<?=e((int)$settings[$key])?>"></div><?php endforeach;?></section><?php endforeach;?></div><div class="form-actions"><button class="btn btn-primary" type="submit">Save &amp; recalculate</button></div></form>
<?php require dirname(__DIR__).'/includes/admin-footer.php';?>
